/**
 * Stability Databank mapping — replaces localStorage Configuration modal.
 * Cropped CSVs live at /databank/CFG{n}/{SCL|ROCOF|PHJUMP|VSTEP}{.pre|.post}.csv
 * (generated by: npm run prepare:databank from Databank_Aug14/ — crop only, no downsample).
 * Local preferred: FastAPI GET /api/v1/series/{CFG}/{EVENT}?phase=pre|post
 *
 * CFG12 (Red Eléctrica / Engie Madrid): /databank/CFG12/{bess|syncon|combined}/*.csv
 * (generated by: npm run prepare:cfg12)
 *
 * CFG13 (AEMO / Transgrid): /databank/CFG13/{bess|syncon|combined}/*.csv
 * (generated by: npm run prepare:cfg13)
 *
 * Event times + dial formulas: Databank_Aug14/Databank_Info_Aug14.xlsx
 * Chart signals (Fault/RoCoF): Sheet1 — Iq/Ip pu (CFG11 Sheet1 still lists *_kA, units pu);
 * VoltageStep/PhaseJump: CFG11 has PHJUMP/VSTEP databank CSVs (event at 40 s).
 * Event details: Databank_Info_Aug14.xlsx → EventDetails (slide 14 right panel).
 */

export type StabilityEventType = 'fault' | 'rocof' | 'phase_jump' | 'voltage_step';

/** UI event → Databank folder / slim filename stem */
export const EVENT_FOLDER: Record<StabilityEventType, 'SCL' | 'ROCOF' | 'PHJUMP' | 'VSTEP'> = {
  fault: 'SCL',
  rocof: 'ROCOF',
  phase_jump: 'PHJUMP',
  voltage_step: 'VSTEP',
};

/** Hover / right-panel copy from Databank_Info EventDetails sheet */
export type EventDetailInfo = {
  title: string;
  lines: string[];
  plotSignal: string;
};

export const EVENT_DETAILS: Record<StabilityEventType, EventDetailInfo> = {
  fault: {
    title: 'Three Phase Fault',
    lines: [
      'Fault type: ABC-G',
      'Fault duration: 140 ms',
      'Fault impedance: 0.02 + j0.2 Ω',
    ],
    plotSignal: 'V_PM_GEP_pu Main',
  },
  rocof: {
    title: 'ROCOF',
    lines: ['Grid Frequency Rampdown: -1 Hz/s'],
    plotSignal: 'FreqMeasA 220kV',
  },
  voltage_step: {
    title: 'Voltage Step',
    lines: ['Grid Voltage: -10% Prefault'],
    plotSignal: 'V_PM_GEP_pu Main',
  },
  phase_jump: {
    title: 'Phase Jump',
    lines: ['Grid Voltage Phase Angle Step: -20°'],
    plotSignal: 'Theta_p_GEP Main',
  },
};

export function getEventDetails(
  activeEvent: 'none' | StabilityEventType,
): EventDetailInfo | null {
  if (activeEvent === 'none') return null;
  return EVENT_DETAILS[activeEvent] ?? null;
}

