/** DOE Sheet1: RS (SynCon) CB + BESS CB — 0=Close, 1=Open */
export function cfg12BreakerState(mode: Cfg12Mode): {
  rsCb: 'closed' | 'open';
  bessCb: 'closed' | 'open';
  summary: string;
} {
  if (mode === 'bess') {
    return { rsCb: 'open', bessCb: 'closed', summary: 'BESS in service · SynCon (RS) open' };
  }
  if (mode === 'syncon') {
    return { rsCb: 'closed', bessCb: 'open', summary: 'SynCon (RS) in service · BESS open' };
  }
  return { rsCb: 'closed', bessCb: 'closed', summary: 'BESS & SynCon both in service' };
}

