export function cfg12EventAvailable(
  _mode: Cfg12Mode,
  _event: StabilityEventType,
  gridCode: Cfg12GridCode = 'spain',
): boolean {
  return gridCode === 'spain';
}

export function findCfg12Study(
  selection: Cfg12Selection,
  event: StabilityEventType,
): Cfg12Study | undefined {
  const variant =
    event === 'fault'
      ? selection.fault
      : event === 'voltage_step'
        ? selection.voltage_step
        : event === 'phase_jump'
          ? selection.phase_jump
          : 'default';
  return CFG12_SPAIN_STUDIES.find(
    (s) => s.mode === selection.mode && s.event === event && s.variant === variant,
  );
}

/** Apply an Excel study → selection patch (caller also sets activeEvent). */
export function selectionFromCfg12Study(study: Cfg12Study): Cfg12Selection {
  const next: Cfg12Selection = {
    ...CFG12_DEFAULT_SELECTION,
    gridCode: 'spain',
    mode: study.mode,
  };
  if (study.event === 'fault') next.fault = study.variant as Cfg12FaultVariant;
  if (study.event === 'voltage_step') next.voltage_step = study.variant as Cfg12VstepVariant;
  if (study.event === 'phase_jump') next.phase_jump = study.variant as Cfg12PhjumpVariant;
  return next;
}

function cfg12Stem(
  event: StabilityEventType,
  variant: string,
): string | null {
  switch (event) {
    case 'fault':
      return variant === '150' ? 'SCL_150' : 'SCL_450';
    case 'rocof':
      return 'ROCOF';
    case 'voltage_step': {
      const map: Record<string, string> = {
        m10: 'VSTEP_m10',
        p10: 'VSTEP_p10',
        p118: 'VSTEP_p118',
        m15: 'VSTEP_m15',
      };
      return map[variant] ?? 'VSTEP_m10';
    }
    case 'phase_jump': {
      const map: Record<string, string> = {
        m30: 'PHJUMP_m30',
        p30: 'PHJUMP_p30',
        m35: 'PHJUMP_m35',
        p35: 'PHJUMP_p35',
      };
      return map[variant] ?? 'PHJUMP_m30';
    }
    default:
      return null;
  }
}

export function getCfg12CsvUrl(
  mode: Cfg12Mode,
  activeEvent: 'none' | StabilityEventType,
  selection: Cfg12Selection,
  phase: DatabankPhase = 'post',
): string | null {
  if (selection.gridCode !== 'spain') return null;
  const event = resolveEventType(activeEvent);
  const variant =
    event === 'fault'
      ? selection.fault
      : event === 'voltage_step'
        ? selection.voltage_step
        : event === 'phase_jump'
          ? selection.phase_jump
          : selection.rocof;
  const stem = cfg12Stem(event, variant);
  if (!stem) return null;
  if (phase === 'pre') return `/databank/CFG12/${mode}/graph/${stem}.pre.csv`;
  if (phase === 'post') return `/databank/CFG12/${mode}/graph/${stem}.post.csv`;
  return `/databank/CFG12/${mode}/graph/${stem}.post.csv`;
}

export function getCfg12EventDetails(
  mode: Cfg12Mode,
  activeEvent: 'none' | StabilityEventType,
  selection: Cfg12Selection,
): EventDetailInfo | null {
  if (activeEvent === 'none') return null;

  if (selection.gridCode !== 'spain') {
    const opt = CFG12_GRID_CODE_OPTIONS.find((o) => o.id === selection.gridCode);
    return {
      title: opt?.label ?? selection.gridCode,
      lines: [
        'Coming soon — awaiting client Databank CSVs',
        'Spain Grid Code studies are available now',
      ],
      plotSignal: '—',
    };
  }

  const study = findCfg12Study(selection, activeEvent);
  const modeTag =
    mode === 'combined' ? 'BESS & SynCon' : mode === 'bess' ? 'BESS' : 'SynCon';
  const cbs = cfg12BreakerState(mode);
  const cbLine = `RS CB: ${cbs.rsCb === 'closed' ? 'Close' : 'Open'} · BESS CB: ${cbs.bessCb === 'closed' ? 'Close' : 'Open'}`;

  if (study) {
    const plotByEvent: Record<StabilityEventType, string> = {
      fault: 'V_poc1 / Irms_poc1',
      rocof: 'fgrid',
      voltage_step: 'V_poc1',
      phase_jump: 'Ang_poc1',
    };
    return {
      title: study.description,
      lines: [
        `Study ${study.id}`,
        cbLine,
        'Spain Grid Code · Engie Madrid',
      ],
      plotSignal: plotByEvent[activeEvent],
    };
  }

  return {
    title: `${activeEvent} — ${modeTag}`,
    lines: [cbLine, 'Spain Grid Code · Engie Madrid'],
    plotSignal: 'P_poc1 / Q_poc1',
  };
}

